import{_ as r,o,c as e,a2 as s}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"모양 및 테마","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/appearance.md","filePath":"ko-KR/user-guide/settings/appearance.md","lastUpdated":1787586465000}'),a={name:"ko-KR/user-guide/settings/appearance.md"};function n(i,t,l,g,d,u){return o(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="모양-및-테마" tabindex="-1">모양 및 테마 <a class="header-anchor" href="#모양-및-테마" aria-label="Permalink to &quot;모양 및 테마&quot;">​</a></h1><p>Lertaro는 세련되고 현대적인 비주얼 디자인 시스템을 갖추고 있으며, 정밀한 테마 모드 전환과 다채로운 색상 팔레트를 제공합니다. 모양 설정은 설정 센터 좌측 사이드바 하단(&quot;정보&quot; 바로 위)에 위치합니다.</p><h2 id="_1-테마-모드-theme-modes" tabindex="-1">1. 테마 모드 (Theme Modes) <a class="header-anchor" href="#_1-테마-모드-theme-modes" aria-label="Permalink to &quot;1. 테마 모드 (Theme Modes)&quot;">​</a></h2><p>상단에 제공되는 세 가지 모드 카드 중 하나를 선택할 수 있습니다.</p><ul><li><strong>라이트 모드 (Light)</strong>: 밝은 인터페이스 스타일로 고정하며 하단 그리드에 라이트 테마만 표시됩니다.</li><li><strong>다크 모드 (Dark)</strong>: 어두운 인터페이스 스타일로 고정하며 하단 그리드에 다크 테마만 표시됩니다.</li><li><strong>시스템 설정 따름 (Follow System)</strong>: Windows 시스템의 밝은/어두운 모드 전환에 맞춰 자동으로 테마가 실시간 변경됩니다. 이 모드에서는 하단 그리드가 <strong>라이트 테마</strong>와 <strong>다크 테마</strong> 선택 영역으로 나뉘어 낮과 밤에 각각 사용할 색상 조합을 지정할 수 있으며 앱 재시작 없이 매끄럽게 전환됩니다.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Lertaro는 라이트 모드와 다크 모드에서 각각 선택한 테마를 독립적으로 기억하므로 모드를 오가도 선택이 초기화되지 않습니다.</p></div><h2 id="_2-테마-선택-카드" tabindex="-1">2. 테마 선택 카드 <a class="header-anchor" href="#_2-테마-선택-카드" aria-label="Permalink to &quot;2. 테마 선택 카드&quot;">​</a></h2><p>테마 선택 영역은 시각적인 썸네일 카드 그리드로 제공됩니다. 각 카드는 검색창, 그림자 테두리, 폰트 위계 및 강조 선택 행의 실제 색상을 정확히 미리 보여주며 현재 적용 중인 테마에는 체크 배지가 표시됩니다.</p><h3 id="기본-및-번들-테마-안내" tabindex="-1">기본 및 번들 테마 안내 <a class="header-anchor" href="#기본-및-번들-테마-안내" aria-label="Permalink to &quot;기본 및 번들 테마 안내&quot;">​</a></h3><ul><li><strong>코어 기본 테마 (CoreExtensions)</strong>: <ul><li><strong>라이트 (Light)</strong> / <strong>다크 (Dark)</strong>: Windows 네이티브 스타일에 자연스럽게 어우러지는 깔끔하고 미니멀한 흑백 기반 디자인.</li><li><strong>노르딕 블루 (Nordic Blue)</strong>: 딥 네이비 배경에 부드러운 아이스 블루 액센트가 어우러진 쿨톤 긱 스타일.</li><li><strong>사쿠라 핑크 (Sakura Pink)</strong>: 은은하고 산뜻한 파스텔톤 핑크 &amp; 화이트 배색.</li><li><strong>사이버펑크 (Cyberpunk)</strong>: 네온 옐로우와 미드나잇 퍼플이 대비를 이루는 미래지향적 감성.</li></ul></li><li><strong>애니메이션 테마 (AnimeThemes, 번들 제공)</strong>: <ul><li><strong>에반게리온 (Evangelion)</strong>, <strong>벚꽃 만개 (Sakura Blossom)</strong>, <strong>날씨의 아이 (Weathering with You)</strong>.</li></ul></li><li><strong>큐레이션 테마 세트 (Curated Themes, 번들 제공)</strong>: <ul><li>라이트/다크가 쌍을 이루는 10가지 세련된 테마: <strong>글래시어 블루 (Glacier Blue)</strong>, <strong>테라코타 (Terracotta)</strong>, <strong>포레스트 그린 (Forest Green)</strong>, <strong>애메지스트 (Amethyst)</strong>, <strong>크림슨 (Crimson)</strong>, <strong>그래파이트 (Graphite)</strong>, <strong>인디고 나이트 (Indigo Night)</strong>, <strong>민트 시안 (Mint Cyan)</strong>, <strong>샴페인 골드 (Champagne Gold)</strong>, <strong>앰버 골드 (Amber Gold)</strong>.</li></ul></li></ul><h3 id="플러그인-테마-확장" tabindex="-1">플러그인 테마 확장 <a class="header-anchor" href="#플러그인-테마-확장" aria-label="Permalink to &quot;플러그인 테마 확장&quot;">​</a></h3><p>모든 테마는 <code>Lertaro.PluginSdk</code>의 UI 테마 표준 규격에 따라 개발되었습니다. 서드파티 개발자는 커스텀 테마 플러그인을 제작하여 이 그리드에 새로운 색상 조합을 등록할 수 있습니다.</p>',12)])])}const p=r(a,[["render",n]]);export{c as __pageData,p as default};
